SourceCode.Declaration:
[TFMDescription("An expression used to create an inventDim string with the dimensions on the buffer. Takes either an inventDim buffer, or inventDimId")]
class MobExpressionsInventDimStr extends TFMExpressions
{
}

Method.Source:
public str processExpressionCommon(Common _common)
{
    SysDictTable    DT = new SysDictTable(_common.TableId);
    SysDictField       DF;
    str dimStr;
    str tempStr;
    int i;
    if (_common.TableID != tableNum(InventDim))
    {
        return 'Not Valid Table';
    }
    for (i = 1; i <= DT.fieldCnt();i++)
    {
        DF = new SysDictField(DT.id(),DT.fieldCnt2Id(i));
        if (DF.name() == fieldStr(InventDim,InventDimId) || DF.name() == fieldStr(InventDim,Sha1HashHex))
        {
            continue;
        }
        tempStr = InventDim::dimReportStr(_common,DT.fieldCnt2Id(i),new xInfo().language());
        dimStr += (tempStr && !DF.isSystem() && !strScan(DF.name(),'hash',1,20) ? (dimStr && tempStr ? ', ' + tempStr :tempStr) : '');
    }
    return dimStr;
}
